  useEffect(() => {
    if (typeof window !== 'undefined') {
      const targetHost = 'www.smartrenowable.energy';
      const currentHost = window.location.hostname;

      // Allow localhost for development, otherwise force redirect to target host
      if (currentHost !== 'localhost' && currentHost !== '127.0.0.1' && currentHost !== targetHost) {
        const targetUrl = new URL(window.location.href);
        targetUrl.hostname = targetHost;
        window.location.replace(targetUrl.toString());
      }
    }
  }, []);

  // Initialize page from URL query parameter if present
  const [currentPage, setCurrentPage] = useState<Page>(() => {
    if (typeof window !== 'undefined') {
      const params = new URLSearchParams(window.location.search);
      const pageParam = params.get('page');
      // Check if the param matches a valid Page enum value
      if (pageParam && Object.values(Page).includes(pageParam as Page)) {
        return pageParam as Page;
      }
    }
    return Page.HOME;
  });

